"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[3209],{8933(e,n,a){a.r(n),a.d(n,{assets:()=>d,contentTitle:()=>p,default:()=>m,frontMatter:()=>l,metadata:()=>i,toc:()=>c});const i=JSON.parse('{"id":"part4-ml-foundations/linear-regression","title":"Linear Regression and Training in PyTorch \u2022 Deep Learning with PyTorch","description":"We\u2019ll connect the math of linear regression to a working PyTorch training loop, keeping the link between equations and code as clear as possible.","source":"@site/docs/part4-ml-foundations/03-linear-regression.mdx","sourceDirName":"part4-ml-foundations","slug":"/part4-ml-foundations/03-linear-regression","permalink":"/tutorials/part4-ml-foundations/03-linear-regression","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":3,"frontMatter":{"title":"Linear Regression and Training in PyTorch \u2022 Deep Learning with PyTorch","slug":"/part4-ml-foundations/03-linear-regression","description":"We\u2019ll connect the math of linear regression to a working PyTorch training loop, keeping the link between equations and code as clear as possible.","sidebar_label":"3. Linear regression","pagination_label":"3. Linear regression","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"2. Machine learning as geometry","permalink":"/tutorials/part4-ml-foundations/02-ml-as-geometry"},"next":{"title":"4. Linear classification","permalink":"/tutorials/part4-ml-foundations/04-linear-classification"}}');var t=a(4848),r=a(8453),o=a(8172);const s=JSON.parse('{"sourcePath":"part4-ml-foundations/03-linear-regression.html","route":"/part4-ml-foundations/03-linear-regression","kind":"chapter","partId":"part4","partLabel":"Part IV - Machine Learning Foundations","accent":"amber","heading":"Linear Regression and Training in PyTorch","title":"Linear Regression and Training in PyTorch \u2022 Deep Learning with PyTorch","description":"We\u2019ll connect the math of linear regression to a working PyTorch training loop, keeping the link between equations and code as clear as possible.","readingMinutes":6,"bodyClass":"","normalizeMath":true,"toc":[{"id":"dataset-notation","label":"2.1 A Simple Dataset and Notation"},{"id":"model-line","label":"2.2 The Model: A Straight Line"},{"id":"loss-mse","label":"2.3 The Loss Function: Mean Squared Error"},{"id":"minimizing","label":"2.4 Learning as Minimizing the Loss"},{"id":"optimizer","label":"2.5 The Optimizer: SGD"},{"id":"training-loop","label":"2.6 The Training Loop"},{"id":"results","label":"2.7 Getting Results Out"},{"id":"summary","label":"2.8 Summary"}],"html":"<div class=\\"wrap\\">\\n            <article class=\\"card\\">\\n                <div class=\\"card__topbar\\" aria-hidden=\\"true\\"></div>\\n\\n                <header>\\n                    <div class=\\"kicker\\">Chapter 3 \u2022 Linear Regression</div>\\n                    \\n                    <p class=\\"subtitle\\">\\n                        We\u2019ll connect the math of linear regression to a working PyTorch training loop, keeping\\n                        the link between equations and code as clear as possible.\\n                    </p>\\n                </header>\\n\\n                <main>\\n                    <p>\\n                        In the previous chapter we viewed machine learning as a geometry problem: data become\\n                        points in a space; models are shapes (lines, planes, curves) that we fit or use to\\n                        separate those points. In this chapter we make that concrete with the simplest possible\\n                        model: linear regression in PyTorch.\\n                    </p>\\n\\n                    <figure class=\\"figure\\">\\n                        <img src=\\"/tutorials/images/ml-regression-line.svg\\" alt=\\"A scatter plot with a best-fit line illustrating linear regression.\\" loading=\\"lazy\\">\\n                        <figcaption>\\n                            The linear regression picture: fit a straight line to data points.\\n                        </figcaption>\\n                    </figure>\\n\\n                    <hr>\\n\\n                    <section class=\\"section\\" aria-labelledby=\\"dataset-notation\\">\\n                        <h2 id=\\"dataset-notation\\">2.1 A Simple Dataset and Notation</h2>\\n                        <p>Consider a dataset with one input feature and one target. For example:</p>\\n                        <ul>\\n                            <li>$x$: years of experience</li>\\n                            <li>$y$: salary</li>\\n                        </ul>\\n\\n                        <p>We have $N$ samples:</p>\\n                        <p>$$ (x_1, y_1), (x_2, y_2), \\\\dots, (x_N, y_N). $$</p>\\n\\n                        <p>\\n                            Here, capital $N$ denotes the total number of samples. The input values $x_i$ and\\n                            target values $y_i$ are fixed; our job is to learn a function that maps\\n                            $x_i \\\\mapsto \\\\hat{y}_i$ so that predictions $\\\\hat{y}_i$ are close to the true values\\n                            $y_i$.\\n                        </p>\\n\\n                        <p>In PyTorch, we store the data as tensors:</p>\\n                        <pre><code class=\\"language-python\\">import torch\\n\\n# Toy example\\nx = torch.tensor([1.0, 2.0, 3.0, 4.0]).view(-1, 1)  # shape: (N, 1)\\ny = torch.tensor([2.0, 4.0, 6.0, 8.0]).view(-1, 1)  # shape: (N, 1)</code></pre>\\n\\n                        <p>\\n                            The <code>.view(-1, 1)</code> reshapes the 1D tensors into column vectors of shape\\n                            $(N, 1)$, which is the common shape for a single input feature and single output in\\n                            PyTorch.\\n                        </p>\\n                    </section>\\n\\n                    <section class=\\"section\\" aria-labelledby=\\"model-line\\">\\n                        <h2 id=\\"model-line\\">2.2 The Model: A Straight Line</h2>\\n                        <p>For simple linear regression, our model is a straight line:</p>\\n                        <p>$$ \\\\hat{y} = m x + b. $$</p>\\n\\n                        <p>For each sample $i$:</p>\\n                        <p>$$ \\\\hat{y}_i = m x_i + b. $$</p>\\n\\n                        <p>\\n                            The parameters $m$ (slope) and $b$ (intercept) are unknown; these are what we want to\\n                            learn from data.\\n                        </p>\\n\\n                        <p>In PyTorch we represent this line with <code>nn.Linear</code>:</p>\\n                        <pre><code class=\\"language-python\\">import torch.nn as nn\\n\\n# One input feature, one output\\nmodel = nn.Linear(in_features=1, out_features=1)</code></pre>\\n\\n                        <p>\\n                            This model internally stores a weight and a bias, which correspond to $m$ and $b$:\\n                        </p>\\n                        <pre><code class=\\"language-python\\">print(model.weight)  # corresponds roughly to m\\nprint(model.bias)    # corresponds roughly to b</code></pre>\\n\\n                        <p>To get predictions, we call the model like a function:</p>\\n                        <pre><code class=\\"language-python\\">y_pred = model(x)  # computes y_hat = m * x + b for all samples</code></pre>\\n\\n                        <p>\\n                            Conceptually, this is computing all the $\\\\hat{y}_i = m x_i + b$ at once using tensor\\n                            operations.\\n                        </p>\\n                    </section>\\n\\n                    <section class=\\"section\\" aria-labelledby=\\"loss-mse\\">\\n                        <h2 id=\\"loss-mse\\">2.3 The Loss Function: Mean Squared Error</h2>\\n                        <p>\\n                            To evaluate how good a particular line is, we measure how far the predictions are from\\n                            the true values. For regression, the standard choice is Mean Squared Error (MSE):\\n                        </p>\\n\\n                        <p>\\n                            $$ L(m, b) = \\\\frac{1}{N} \\\\sum_{i=1}^{N} \\\\bigl(y_i - \\\\hat{y}_i\\\\bigr)^2. $$\\n                        </p>\\n\\n                        <p>Substituting the model $\\\\hat{y}_i = m x_i + b$, we can write:</p>\\n                        <p>\\n                            $$ L(m, b) = \\\\frac{1}{N} \\\\sum_{i=1}^{N} \\\\bigl(y_i - (m x_i + b)\\\\bigr)^2. $$\\n                        </p>\\n\\n                        <p>\\n                            Geometrically, $\\\\lvert y_i - \\\\hat{y}_i \\\\rvert$ is the vertical distance from the point\\n                            $(x_i, y_i)$ to the line. Squaring and averaging gives us a single non-negative number\\n                            that is small when the line fits the data well and large when it does not.\\n                        </p>\\n\\n                        <p>In PyTorch, we use <code>nn.MSELoss</code>:</p>\\n                        <pre><code class=\\"language-python\\">criterion = nn.MSELoss()\\n\\ny_pred = model(x)\\nloss = criterion(y_pred, y)  # scalar tensor: the MSE\\nprint(loss.item())</code></pre>\\n\\n                        <p>\\n                            At this point we have everything needed to define a supervised learning problem:\\n                        </p>\\n                        <ul>\\n                            <li>a model $\\\\hat{y} = m x + b$, and</li>\\n                            <li>\\n                                a loss function $L(m, b)$ that tells us how good any particular choice of $m$ and\\n                                $b$ is.\\n                            </li>\\n                        </ul>\\n                    </section>\\n\\n                    <section class=\\"section\\" aria-labelledby=\\"minimizing\\">\\n                        <h2 id=\\"minimizing\\">2.4 Learning as Minimizing the Loss</h2>\\n                        <p>\\n                            The data $(x_i, y_i)$ are given and fixed. The variables in the loss expression are the\\n                            parameters $m$ and $b$. Learning means:\\n                        </p>\\n                        <p>$$ (m^*, b^*) = \\\\arg\\\\min_{m, b} L(m, b). $$</p>\\n\\n                        <p>\\n                            In other words, we want to find the values of $m$ and $b$ that make the mean squared\\n                            error as small as possible.\\n                        </p>\\n\\n                        <p>\\n                            For very simple models like this, you can derive explicit formulas for $m^*$ and $b^*$\\n                            by taking derivatives of $L$ with respect to $m$ and $b$, setting them to zero, and\\n                            solving:\\n                        </p>\\n                        <p>$$ \\\\frac{\\\\partial L}{\\\\partial m} = 0, \\\\qquad \\\\frac{\\\\partial L}{\\\\partial b} = 0. $$</p>\\n\\n                        <p>\\n                            The normal-equation approach is useful theory, and closed-form or direct solvers remain\\n                            important for some linear models. However, this approach does not generalize cleanly to\\n                            deep neural networks, where the loss depends on thousands or millions of parameters in\\n                            highly nonlinear ways. For those models, we use gradient-based iterative methods.\\n                        </p>\\n\\n                        <p>\\n                            For a parameter vector $\\\\theta$ (in our case $\\\\theta = \\\\{m, b\\\\}$), classic gradient\\n                            descent updates parameters as:\\n                        </p>\\n                        <p>$$ \\\\theta \\\\leftarrow \\\\theta - \\\\eta \\\\nabla_\\\\theta L(\\\\theta), $$</p>\\n\\n                        <p>where $\\\\eta &gt; 0$ is the learning rate. Applied to our parameters, this becomes:</p>\\n                        <p>\\n                            $$ m \\\\leftarrow m - \\\\eta \\\\frac{\\\\partial L}{\\\\partial m}, \\\\qquad\\n                            b \\\\leftarrow b - \\\\eta \\\\frac{\\\\partial L}{\\\\partial b}. $$\\n                        </p>\\n\\n                        <p>\\n                            PyTorch computes these derivatives automatically using automatic differentiation. Our\\n                            job is to define the model, the loss, and the optimization procedure; PyTorch will\\n                            handle the gradients.\\n                        </p>\\n                    </section>\\n\\n                    <section class=\\"section\\" aria-labelledby=\\"optimizer\\">\\n                        <h2 id=\\"optimizer\\">2.5 The Optimizer: SGD</h2>\\n                        <p>\\n                            We now need a component that takes the gradients and updates the parameters. PyTorch\\n                            provides several optimizers; the simplest is Stochastic Gradient Descent (SGD):\\n                        </p>\\n                        <pre><code class=\\"language-python\\">import torch.optim as optim\\n\\nlearning_rate = 0.01\\noptimizer = optim.SGD(model.parameters(), lr=learning_rate)</code></pre>\\n\\n                        <p>\\n                            Here, <code>model.parameters()</code> returns an iterator over the model\u2019s trainable\\n                            parameters (in this case, the weight and bias). The optimizer will update these\\n                            in-place, using the gradients that PyTorch computes.\\n                        </p>\\n                    </section>\\n\\n                    <section class=\\"section\\" aria-labelledby=\\"training-loop\\">\\n                        <h2 id=\\"training-loop\\">2.6 The Training Loop</h2>\\n                        <p>\\n                            Training consists of repeating the same sequence of steps: zeroing gradients, computing\\n                            predictions, computing the loss, computing gradients, and updating parameters. Each\\n                            full pass through these steps is one training iteration; when we apply this to the\\n                            whole dataset repeatedly, we often call each pass through the dataset an epoch.\\n                        </p>\\n\\n                        <figure class=\\"figure\\">\\n                            <img src=\\"/tutorials/images/pytorch-training-loop.svg\\" alt=\\"A flow diagram of a PyTorch training iteration: zero_grad, forward pass, compute loss, backward, optimizer step, repeat.\\" loading=\\"lazy\\">\\n                            <figcaption>\\n                                The standard PyTorch training pattern you\u2019ll reuse in nearly every model.\\n                            </figcaption>\\n                        </figure>\\n\\n                        <p>A typical training loop for simple linear regression looks like this:</p>\\n                        <pre><code class=\\"language-python\\">num_epochs = 1000\\n\\nfor epoch in range(num_epochs):\\n    # 1. Zero out previous gradients\\n    optimizer.zero_grad()\\n\\n    # 2. Forward pass: compute predictions\\n    y_pred = model(x)\\n\\n    # 3. Compute the loss\\n    loss = criterion(y_pred, y)\\n\\n    # 4. Backward pass: compute gradients dL/dm and dL/db\\n    loss.backward()\\n\\n    # 5. Update parameters using the optimizer\\n    optimizer.step()\\n\\n    # (Optional) monitor progress\\n    if (epoch + 1) % 100 == 0:\\n        print(f\\"Epoch {epoch + 1}, Loss = {loss.item():.4f}\\")</code></pre>\\n\\n                        <p>The mapping to the math is direct:</p>\\n                        <ul>\\n                            <li><code>y_pred = model(x)</code> computes all $\\\\hat{y}_i = m x_i + b$.</li>\\n                            <li><code>loss = criterion(y_pred, y)</code> computes $L(m, b)$.</li>\\n                            <li>\\n                                <code>loss.backward()</code> fills in <code>model.weight.grad</code> and\\n                                <code>model.bias.grad</code> with $\\\\frac{\\\\partial L}{\\\\partial m}$ and\\n                                $\\\\frac{\\\\partial L}{\\\\partial b}$.\\n                            </li>\\n                            <li><code>optimizer.step()</code> performs the gradient descent updates.</li>\\n                        </ul>\\n                    </section>\\n\\n                    <section class=\\"section\\" aria-labelledby=\\"results\\">\\n                        <h2 id=\\"results\\">2.7 Getting Results Out</h2>\\n                        <p>\\n                            After training, we may want to inspect predictions or plot the learned line. Since many\\n                            plotting libraries expect NumPy arrays, we often convert our tensors:\\n                        </p>\\n                        <pre><code class=\\"language-python\\">with torch.no_grad():       # disable gradient tracking\\n        y_pred = model(x)       # final predictions\\n\\nx_np = x.detach().numpy()\\ny_np = y.detach().numpy()\\ny_pred_np = y_pred.detach().numpy()</code></pre>\\n\\n                        <p>\\n                            The <code>detach()</code> call removes tensors from the computation graph, making\\n                            conversion to NumPy safe. We can then plot <code>x_np</code> versus <code>y_np</code>\\n                            and <code>y_pred_np</code> using Matplotlib, or use them in further analysis.\\n                        </p>\\n                    </section>\\n\\n                    <section class=\\"section\\" aria-labelledby=\\"summary\\">\\n                        <h2 id=\\"summary\\">2.8 Summary</h2>\\n                        <p>\\n                            In this chapter we connected the geometric picture of linear regression to both its\\n                            mathematical formulation and its PyTorch implementation. We started with a set of data\\n                            points $(x_i, y_i)$, defined a linear model:\\n                        </p>\\n                        <p>$$ \\\\hat{y} = m x + b, $$</p>\\n\\n                        <p>and measured its performance using the mean squared error:</p>\\n                        <p>\\n                            $$ L(m, b) = \\\\frac{1}{N} \\\\sum_{i=1}^{N} \\\\bigl(y_i - (m x_i + b)\\\\bigr)^2. $$\\n                        </p>\\n\\n                        <p>\\n                            We then viewed learning as minimizing this loss with respect to the parameters $m$ and\\n                            $b$:\\n                        </p>\\n                        <p>$$ (m^*, b^*) = \\\\arg\\\\min_{m, b} L(m, b), $$</p>\\n\\n                        <p>\\n                            and we implemented this using PyTorch\u2019s tensors, <code>nn.Linear</code> model,\\n                            <code>nn.MSELoss</code> loss function, and an SGD optimizer inside a training loop.\\n                        </p>\\n\\n                        <div class=\\"callout\\" role=\\"note\\">\\n                            This simple example is more than a toy: the same pattern\u2014define data, define model,\\n                            define loss, define optimizer, write a training loop\u2014will reappear in every deep\\n                            learning model we build with PyTorch, from basic neural networks to convolutional and\\n                            recurrent architectures.\\n                        </div>\\n                    </section>\\n                </main>\\n\\n                <div class=\\"footer\\">Deep Learning with PyTorch \u2022 Linear Regression</div>\\n            </article>\\n        </div>"}'),l={title:"Linear Regression and Training in PyTorch \u2022 Deep Learning with PyTorch",slug:"/part4-ml-foundations/03-linear-regression",description:"We\u2019ll connect the math of linear regression to a working PyTorch training loop, keeping the link between equations and code as clear as possible.",sidebar_label:"3. Linear regression",pagination_label:"3. Linear regression",hide_title:!0,hide_table_of_contents:!0},p=void 0,d={},c=[];function h(e){return(0,t.jsx)(o.A,{content:s})}function m(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(h,{...e})}):h()}}}]);